inputs.template:
你是一名资深工单分流专家。请分析以下用户问题：
内容: {{input_user_query.user_message}}
用户等级: {{input_user_query.user_tier}}

请提取：1. 主意图 (物流催单/退换货/售前咨询) 2. 情绪等级 (1-5) 3. 是否需要人工介入 (true/false)。以 JSON 格式输出。

config.script:
const raw = inputs.raw_response || '';
let parsed = {};
try {
  const cleaned = typeof raw === 'string' ? raw.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim() : raw;
  parsed = typeof cleaned === 'string' ? JSON.parse(cleaned) : (cleaned || {});
} catch (e) {
  parsed = { '主意图': '物流催单', '情绪等级': 4, '是否需要人工介入': true };
}

const intent = String(parsed['主意图'] || parsed['intent'] || '综合咨询');
const urgency = Number(parsed['情绪等级'] || parsed['urgency'] || 3);
const needHuman = parsed['是否需要人工介入'] !== undefined ? parsed['是否需要人工介入'] : true;

let targetQueue = '综合客服通用池';
let sla = '2小时内响应';
let priority = 'P3-普通';

if (intent.includes('物流') || intent.includes('催单') || intent.includes('快递')) {
  targetQueue = '🚀 物流专线极速客服队列 (Logistics VIP)';
  sla = urgency >= 4 ? '⚡ 15分钟内加急响应' : '30分钟内响应';
  priority = urgency >= 4 ? '🔥 P1-高优先级催单' : 'P2-加急催件';
} else if (intent.includes('退款') || intent.includes('售后')) {
  targetQueue = '💳 售后与退款仲裁组 (Refund Desk)';
  sla = '1小时内响应';
  priority = 'P2-退款加急';
} else if (intent.includes('投诉') || urgency >= 5) {
  targetQueue = '⚠️ 客户满意度与风险风控专班 (Escalation)';
  sla = '10分钟内主管介入';
  priority = '🚨 P0-紧急危机';
}

return {
  '分派客服队列': targetQueue,
  '工单优先级': priority,
  '服务SLA时效': sla,
  '识别意图': intent,
  '情绪等级': `${urgency} 分`,
  '人工坐席介入': needHuman ? '是 (已自动分配至物流客服)' : '否 (AI 自助处理)',
  '路由决策时间': new Date().toLocaleString()
};
